    mime: "text/html; charset=utf-8",
    body: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Public Advertisement Kiosk | NTTF Mechatronics</title>\n  <link rel=\"stylesheet\" href=\"src/styles.css\">\n  <style>\n    /* Fullscreen Kiosk specific styling */\n    html, body {\n      height: 100%;\n      overflow: hidden;\n      background: radial-gradient(circle at 80% 20%, #09172e 0%, #03060d 70%);\n    }\n  </style>\n</head>\n<body class=\"kiosk-body\">\n\n  <!-- Kiosk Top Navigation Bar -->\n  <header class=\"kiosk-header\">\n    <div style=\"display: flex; align-items: center; gap: 14px;\">\n      <div class=\"logo-badge\" style=\"width: 32px; height: 32px; font-size: 14px;\">🤖</div>\n      <div>\n        <h1 style=\"font-size: 15px; font-weight: 800; color: #fff;\" data-i18n=\"collegeName\">Autonomous AI Robot</h1>\n        <span style=\"font-size: 11px; color: var(--cyan-primary);\" data-i18n=\"deptName\">Smart Advertising System</span>\n      </div>\n    </div>\n\n    <div style=\"display: flex; align-items: center; gap: 16px;\">\n      <!-- AI Voice Assistant Availability Pill -->\n      <div class=\"status-pill\" style=\"border-color: rgba(0, 240, 255, 0.4); background: rgba(0, 240, 255, 0.08);\">\n        <span style=\"color: var(--cyan-primary); font-size: 14px;\">🎙️</span>\n        <span style=\"color: #fff; font-size: 12px; font-weight: 600;\" data-i18n=\"aiListening\">Say \"Hey Robot\" to ask any question</span>\n      </div>\n\n      <!-- Robot Hardware Status Pill -->\n      <div id=\"robot-status-badge\" class=\"status-pill\">\n        <span id=\"robot-status-dot\" class=\"status-dot offline\"></span>\n        <span id=\"robot-status-text\" data-i18n=\"robotStatus\">Robot Status</span>\n      </div>\n\n      <!-- Bilingual Language Toggle Button -->\n      <button id=\"btn-lang-toggle\" class=\"btn btn-secondary btn-sm\" style=\"border-radius: var(--radius-full); padding: 6px 14px; font-weight: bold;\">\n        🌐 <span data-i18n=\"switchLanguage\">മലയാളം</span>\n      </button>\n    </div>\n  </header>\n\n  <!-- Kiosk Main Presentation Area -->\n  <main class=\"kiosk-main\">\n    <!-- Left Column: Large Advertisement Poster -->\n    <div class=\"kiosk-poster-col\">\n      <img id=\"kiosk-poster\" class=\"kiosk-poster-img\" src=\"/assets/ads/nttf_mechatronics.svg\" alt=\"Active Advertisement Poster\">\n    </div>\n\n    <!-- Right Column: Product Information & Live Highlights -->\n    <div class=\"kiosk-info-col\">\n      <span id=\"kiosk-category\" class=\"kiosk-badge\">College / Education</span>\n      <h2 id=\"kiosk-title\" class=\"kiosk-title\">NTTF Technical Training Centre</h2>\n      <div id=\"kiosk-price\" class=\"kiosk-price-tag\">₹75,000</div>\n      <p id=\"kiosk-desc\" class=\"kiosk-desc\">\n        Join the premier Diploma in Mechatronics Engineering. Hands-on training in Robotics, Embedded IoT, PLC Automation, and guaranteed industrial placement.\n      </p>\n\n      <ul id=\"kiosk-features\" class=\"kiosk-features-list\">\n        <li>Hands-on Industrial Robotics &amp; AGV Labs</li>\n        <li>Dual Core ESP32-S3 &amp; Embedded AI Architecture</li>\n        <li>100% Practical Industry-Aligned Curriculum</li>\n        <li>Over 95% Verified Campus Placements</li>\n      </ul>\n\n      <div id=\"kiosk-promo\" style=\"display: block; padding: 12px 18px; background: rgba(255, 210, 0, 0.1); border: 1px solid #ffd200; border-radius: var(--radius-md); color: #ffd200; font-weight: 700; font-size: 15px;\">\n        🎁 Early bird scholarship of ₹10,000 for top entrance rankers.\n      </div>\n    </div>\n  </main>\n\n  <!-- Kiosk Bottom Status Ticker -->\n  <footer class=\"kiosk-footer-ticker\">\n    <div style=\"display: flex; gap: 20px; align-items: center;\">\n      <span style=\"color: var(--cyan-primary); font-weight: 700;\">📡 BROADCAST KIOSK</span>\n      <span style=\"color: var(--text-dim);\">|</span>\n      <span>Live Display Synchronized with Robot 10-Inch DWIN HMI Screen</span>\n    </div>\n    <div>\n      <span style=\"font-size: 12px; color: var(--text-dim);\">Autonomous AI Advertisement Robot © 2026</span>\n    </div>\n  </footer>\n\n  <script type=\"module\" src=\"src/kiosk.js\"></script>\n</body>\n</html>\n"
